    Bug 382977 - Add "Show Full Path" folder pane option for compact view modes. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D272221

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 41988bf520c..9958bae17eb 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -1848,6 +1848,7 @@ var folderPane = {
     }
     this.activeModes = currentModes;
     this.toggleCompactViewMenuItem();
+    this.toggleFullPathMenuItem();

     if (this.activeModes.length == 1 && this.activeModes.at(0) == "all") {
       this.updateContextCheckedFolderMode();
@@ -1865,6 +1866,17 @@ var folderPane = {
     subMenuCompactBtn.setAttribute("disabled", "true");
   },

+  toggleFullPathMenuItem() {
+    const fullPathBtn = document.querySelector(
+      "#folderPaneHeaderToggleFullPath"
+    );
+    if (this.canBeCompact && this.isCompact) {
+      fullPathBtn.removeAttribute("disabled");
+    } else {
+      fullPathBtn.setAttribute("disabled", "true");
+    }
+  },
+
   /**
    * Ensure all the folder modes menuitems in the pane header context menu are
    * checked to reflect the currently active modes.
@@ -1933,6 +1945,7 @@ var folderPane = {
    */
   compactFolderToggle(event) {
     this.isCompact = event.target.hasAttribute("checked");
+    this.toggleFullPathMenuItem();
   },

   /**
@@ -4079,6 +4092,12 @@ var folderPane = {
             ? item.setAttribute("checked", true)
             : item.removeAttribute("checked");
           break;
+        case "folderPaneHeaderToggleFullPath":
+          XULStoreUtils.isItemVisible("messenger", "folderPaneFullPath")
+            ? item.setAttribute("checked", true)
+            : item.removeAttribute("checked");
+          this.toggleFullPathMenuItem();
+          break;
         case "folderPaneHeaderToggleLocalFolders":
           XULStoreUtils.isItemHidden("messenger", "folderPaneLocalFolders")
             ? item.setAttribute("checked", true)
@@ -4153,6 +4172,17 @@ var folderPane = {
     }
   },

+  /**
+   * Toggle the full path option and update the XULStore.
+   */
+  toggleFullPath(event) {
+    const show = event.target.hasAttribute("checked");
+    XULStoreUtils.setValue("messenger", "folderPaneFullPath", "visible", show);
+    for (const row of document.querySelectorAll(`li[is="folder-tree-row"]`)) {
+      row.updateFolderNames();
+    }
+  },
+
   /**
    * Toggle the hiding of the local folders and update the XULStore.
    */
diff --git a/mail/base/content/about3Pane.xhtml b/mail/base/content/about3Pane.xhtml
index 710c6b7a3da..c2e8603c1ac 100644
--- a/mail/base/content/about3Pane.xhtml
+++ b/mail/base/content/about3Pane.xhtml
@@ -572,6 +572,12 @@
               closemenu="none"
               data-l10n-id="folder-pane-header-toggle-folder-size"
               oncommand="folderPane.toggleFolderSize(event);"/>
+    <menuitem id="folderPaneHeaderToggleFullPath"
+              class="folder-pane-option"
+              type="checkbox"
+              closemenu="none"
+              data-l10n-id="folder-pane-header-toggle-full-path"
+              oncommand="folderPane.toggleFullPath(event);"/>
     <menuitem id="folderPaneHeaderToggleLocalFolders"
               class="folder-pane-option"
               type="checkbox"
diff --git a/mail/base/content/widgets/folder-tree-row.mjs b/mail/base/content/widgets/folder-tree-row.mjs
index e88f1f618f0..de1899481dc 100644
--- a/mail/base/content/widgets/folder-tree-row.mjs
+++ b/mail/base/content/widgets/folder-tree-row.mjs
@@ -124,8 +124,16 @@ class FolderTreeRow extends HTMLLIElement {
         this.fullName = this._fullFolderName;
         break;
       case "both":
-        this.name = `${this._folderName} - ${this._serverName}`;
-        this.fullName = `${this._fullFolderName} - ${this._serverName}`;
+        {
+          const folderName = lazy.XULStoreUtils.isItemVisible(
+            "messenger",
+            "folderPaneFullPath"
+          )
+            ? this._fullFolderName
+            : this._folderName;
+          this.name = `${folderName} - ${this._serverName}`;
+          this.fullName = `${this._fullFolderName} - ${this._serverName}`;
+        }
         break;
     }
   }
diff --git a/mail/locales/en-US/messenger/about3Pane.ftl b/mail/locales/en-US/messenger/about3Pane.ftl
index 7ab2c38657d..0ae57b42003 100644
--- a/mail/locales/en-US/messenger/about3Pane.ftl
+++ b/mail/locales/en-US/messenger/about3Pane.ftl
@@ -223,6 +223,10 @@ folder-pane-show-total-toggle =
 folder-pane-header-toggle-folder-size =
   .label = Show Folder Size

+# Context menu item to toggle display of full folder path in compact mode.
+folder-pane-header-toggle-full-path =
+  .label = Show Full Path
+
 folder-pane-header-hide-local-folders =
   .label = Hide Local Folders
